IF OBJECT_ID(N'dbo.CK_PurchaseOrderLine_qty', N'C') IS NOT NULL ALTER TABLE [dbo].[PurchaseOrderLine] DROP CONSTRAINT [CK_PurchaseOrderLine_qty];
ALTER TABLE [dbo].[PurchaseOrderLine] WITH CHECK ADD CONSTRAINT [CK_PurchaseOrderLine_qty] CHECK ([qty] > 0 AND [rate] > 0 AND [received] BETWEEN 0 AND [qty] AND [accepted] BETWEEN 0 AND [received]);
IF OBJECT_ID(N'dbo.CK_GoodsReceiptLine_qty', N'C') IS NOT NULL ALTER TABLE [dbo].[GoodsReceiptLine] DROP CONSTRAINT [CK_GoodsReceiptLine_qty];
ALTER TABLE [dbo].[GoodsReceiptLine] WITH CHECK ADD CONSTRAINT [CK_GoodsReceiptLine_qty] CHECK ([received] > 0 AND [accepted] BETWEEN 0 AND [received]);
IF OBJECT_ID(N'dbo.CK_VendorBill_amounts', N'C') IS NOT NULL ALTER TABLE [dbo].[VendorBill] DROP CONSTRAINT [CK_VendorBill_amounts];
ALTER TABLE [dbo].[VendorBill] WITH CHECK ADD CONSTRAINT [CK_VendorBill_amounts] CHECK ([subtotal] > 0 AND [gst] >= 0 AND [total] = [subtotal] + [gst] AND [expected] >= 0);
IF OBJECT_ID(N'dbo.CK_VendorPayment_amounts', N'C') IS NOT NULL ALTER TABLE [dbo].[VendorPayment] DROP CONSTRAINT [CK_VendorPayment_amounts];
ALTER TABLE [dbo].[VendorPayment] WITH CHECK ADD CONSTRAINT [CK_VendorPayment_amounts] CHECK ([gross] > 0 AND [tds] >= 0 AND [net] = [gross] - [tds]);
IF OBJECT_ID(N'dbo.CK_PettyCashVoucher_amount', N'C') IS NOT NULL ALTER TABLE [dbo].[PettyCashVoucher] DROP CONSTRAINT [CK_PettyCashVoucher_amount];
ALTER TABLE [dbo].[PettyCashVoucher] WITH CHECK ADD CONSTRAINT [CK_PettyCashVoucher_amount] CHECK ([amount] > 0);
IF OBJECT_ID(N'dbo.CK_Membership_scope', N'C') IS NOT NULL ALTER TABLE [dbo].[Membership] DROP CONSTRAINT [CK_Membership_scope];
ALTER TABLE [dbo].[Membership] WITH CHECK ADD CONSTRAINT [CK_Membership_scope] CHECK (([scopeType] = N'ORG' AND [regionId] IS NULL AND [branchId] IS NULL) OR ([scopeType] = N'REGION' AND [regionId] IS NOT NULL AND [branchId] IS NULL) OR ([scopeType] = N'BRANCH' AND [branchId] IS NOT NULL AND [regionId] IS NULL));

